CREATE TABLE brands (
	id SERIAL NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

CREATE TABLE hubs (
	id SERIAL NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	address VARCHAR(200) NOT NULL, 
	capacity INTEGER NOT NULL, 
	rain_mode BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);

CREATE TABLE vouchers (
	id SERIAL NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	description VARCHAR(200) NOT NULL, 
	discount_type VARCHAR(10) NOT NULL, 
	value INTEGER NOT NULL, 
	valid_from TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	valid_to TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	min_order INTEGER NOT NULL, 
	usage_limit INTEGER, 
	used_count INTEGER NOT NULL, 
	once_per_customer BOOLEAN NOT NULL, 
	active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
);

CREATE TABLE menu_items (
	id SERIAL NOT NULL, 
	brand_id INTEGER NOT NULL, 
	name_vi VARCHAR(120) NOT NULL, 
	name_en VARCHAR(120) NOT NULL, 
	price INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(brand_id) REFERENCES brands (id)
);

CREATE TABLE users (
	id SERIAL NOT NULL, 
	username VARCHAR(40) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	full_name VARCHAR(80) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	customer_type VARCHAR(10), 
	phone VARCHAR(30), 
	email VARCHAR(120), 
	hub_id INTEGER, 
	PRIMARY KEY (id), 
	UNIQUE (username), 
	FOREIGN KEY(hub_id) REFERENCES hubs (id)
);

CREATE TABLE hub_menu_items (
	hub_id INTEGER NOT NULL, 
	menu_item_id INTEGER NOT NULL, 
	available BOOLEAN NOT NULL, 
	PRIMARY KEY (hub_id, menu_item_id), 
	FOREIGN KEY(hub_id) REFERENCES hubs (id), 
	FOREIGN KEY(menu_item_id) REFERENCES menu_items (id)
);

CREATE TABLE orders (
	id SERIAL NOT NULL, 
	number VARCHAR(20), 
	customer_id INTEGER NOT NULL, 
	hub_id INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	delivery_address VARCHAR(250) NOT NULL, 
	distance_km FLOAT NOT NULL, 
	items_subtotal INTEGER NOT NULL, 
	delivery_fee INTEGER NOT NULL, 
	rain_surcharge INTEGER NOT NULL, 
	quiet_discount INTEGER NOT NULL, 
	voucher_id INTEGER, 
	voucher_discount INTEGER NOT NULL, 
	total INTEGER NOT NULL, 
	payment_method VARCHAR(20) NOT NULL, 
	payment_status VARCHAR(20) NOT NULL, 
	reject_reason TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	confirmed_at TIMESTAMP WITHOUT TIME ZONE, 
	delivered_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (number), 
	FOREIGN KEY(customer_id) REFERENCES users (id), 
	FOREIGN KEY(hub_id) REFERENCES hubs (id), 
	FOREIGN KEY(voucher_id) REFERENCES vouchers (id)
);

CREATE TABLE notifications (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	order_id INTEGER, 
	message VARCHAR(250) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(order_id) REFERENCES orders (id)
);

CREATE TABLE order_items (
	id SERIAL NOT NULL, 
	order_id INTEGER NOT NULL, 
	menu_item_id INTEGER NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(order_id) REFERENCES orders (id), 
	FOREIGN KEY(menu_item_id) REFERENCES menu_items (id)
);

CREATE TABLE voucher_redemptions (
	id SERIAL NOT NULL, 
	voucher_id INTEGER NOT NULL, 
	customer_id INTEGER NOT NULL, 
	order_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (order_id), 
	FOREIGN KEY(voucher_id) REFERENCES vouchers (id), 
	FOREIGN KEY(customer_id) REFERENCES users (id), 
	FOREIGN KEY(order_id) REFERENCES orders (id)
);
